const forms = {
 ru:['Расскажи про {x}.','Когда ты в последний раз признавался себе в {x}?','Что было бы, если бы все узнали про {x}?','Кому ты мог бы честно рассказать про {x}?','Что ты скрываешь, когда речь заходит про {x}?','Что в {x} тебе труднее всего принять?'],
 uk:['Розкажи про {x}.','Коли ти востаннє зізнавався собі в {x}?','Що було б, якби всі дізналися про {x}?','Кому ти міг би чесно розповісти про {x}?','Що ти приховуєш, коли йдеться про {x}?','Що в {x} тобі найважче прийняти?']
};
function makeQuestions(id, lang){ const seeds=bankSeeds[id][lang], usedForms=id==='money'?forms[lang].slice(0,5):id==='confession'?forms[lang].slice(0,4):forms[lang]; return seeds.flatMap((x,i)=>usedForms.map((f,j)=>({id:`${id}-${i}-${j}`,category:id,text:f.replace('{x}',x)}))); }
const allQuestions = ['truth','desire','relations','friends','money','confession'].flatMap(id=>makeQuestions(id,'ru'));
const allQuestionsUk = ['truth','desire','relations','friends','money','confession'].flatMap(id=>makeQuestions(id,'uk'));
const questionMap = Object.fromEntries(allQuestions.map(q=>[q.id,q]));
