const state = {view:'home', lang:store.get('lang','ru'), dark:store.get('dark',false), sound:store.get('sound',false), cardSize:store.get('cardSize',100), favorites:store.get('favorites',[]), confessions:store.get('confessions',[]), players:store.get('players',[]), mode:store.get('mode','everyone'), selectedDeck:null, editingGame:false, game:null, modal:null, toast:''};
const t = (key) => copy[state.lang][key];
function setTheme(){ document.documentElement.classList.toggle('dark',state.dark); document.body.classList.toggle('dark',state.dark); }
function questions(lang=state.lang){ return lang==='uk'?allQuestionsUk:allQuestions; }
function getCat(id){return cats.find(c=>c.id===id)}
function shuffle(a){ const n=[...a]; for(let i=n.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[n[i],n[j]]=[n[j],n[i]]}return n; }
function shell(content, active='') { return `<main class="shell"><header class="top"><button class="wordmark" data-go="home">Ооочень <b>провокационная</b></button><div class="top-actions"><button class="round-btn ${state.view==='favorites'?'is-active':''}" aria-label="${t('fav')}" title="${t('fav')}" data-go="favorites">♡</button><button class="round-btn ${state.view==='settings'?'is-active':''}" aria-label="${t('settings')}" title="${t('settings')}" data-go="settings">⚙</button></div></header>${content}${nav(active)}</main>${state.modal?modal():''}${state.toast?`<div class="toast" role="status">${escapeHtml(state.toast)}</div>`:''}`; }
function nav(active){return `<nav class="bottom-nav"><button class="nav-item ${active==='home'?'active':''}" data-go="home"><span class="nav-icon">⌂</span>${t('home')}</button><button class="nav-item ${active==='decks'?'active':''}" data-go="decks"><span class="nav-icon">▣</span>${t('decks')}</button><button class="nav-item ${active==='anon'?'active':''}" data-go="anonymous"><span class="nav-icon">◌</span>${t('anon')}</button></nav>`}
function renderHome(){const uk=state.lang==='uk';return shell(`<section class="hero"><div class="hero-grid"><div><p class="eyebrow">${uk?'Карткова гра для дорослих':'Карточная игра для взрослых'}</p><h1>${t('headline')}</h1><p class="hero-copy">${t('lead')}</p><button class="primary" data-start>${t('start')}</button><p class="hero-note">${t('adult')}</p></div><div class="hero-art" aria-hidden="true"><article class="hero-card"><span class="tiny">${uk?'Запитання 14':'Вопрос 14'}</span><p>${uk?'Що ти не готовий визнати про себе?':'Что ты не готов признать о себе?'}</p><strong>?</strong></article><article class="hero-card"><span class="tiny">${uk?'Без імені':'Без имени'}</span><p>${uk?'Іноді мовчання теж відповідь.':'Иногда молчание тоже ответ.'}</p><strong>—</strong></article></div></div></section>`,'home')}
function renderDecks(){return shell(`<section class="content-page decks-page"><div class="section-heading"><div><p class="eyebrow">06 ${t('deckCount')}</p><h1 class="page-title">${t('deckTitle')}</h1><p class="sub">${t('deckLead')}</p></div><button class="random-deck" data-random-deck><span aria-hidden="true">✳</span><span><strong>${t('randomDeck')}</strong><small>${t('randomDeckHint')}</small></span><b aria-hidden="true">↗</b></button></div><div class="deck-grid">${cats.map((c,i)=>`<button class="deck" data-deck="${c.id}"><span class="deck-num">0${i+1} / 06</span><div><h2>${c.n[state.lang]}</h2><p>${c.d[state.lang]}</p></div><span class="count">${c.total} ${state.lang==='ru'?'вопросов':'запитань'} <span aria-hidden="true">↗</span></span></button>`).join('')}</div></section>`,'decks')}
function renderSetup(){const id=state.selectedDeck,cat=getCat(id),title=cat?cat.n[state.lang]:t('fav');return shell(`<section class="content-page setup-page"><button class="back" data-go="${state.editingGame?'game':id==='favorites'?'favorites':'decks'}">← ${state.editingGame?t('backGame'):id==='favorites'?t('fav'):t('back')}</button><p class="eyebrow">${t('setup')}</p><h1 class="page-title">${escapeHtml(title)}</h1><div class="setup-content"><div><h2 class="section-title">${t('mode')}</h2><div class="mode-options"><button class="mode-option ${state.mode==='everyone'?'selected':''}" data-mode="everyone" aria-pressed="${state.mode==='everyone'}"><span class="mode-symbol">◎</span><span><strong>${t('everyone')}</strong><small>${t('everyoneHint')}</small></span><span class="selection-dot"></span></button><button class="mode-option ${state.mode==='turns'?'selected':''}" data-mode="turns" aria-pressed="${state.mode==='turns'}"><span class="mode-symbol">↻</span><span><strong>${t('turns')}</strong><small>${t('turnsHint')}</small></span><span class="selection-dot"></span></button></div></div><div class="players-panel ${state.mode==='everyone'?'muted-panel':''}"><div class="players-heading"><div><h2 class="section-title">${t('players')}</h2><p>${t('playersHint')}</p></div><span>${state.players.length}</span></div><form id="player-form" class="player-form"><input id="player-name" autocomplete="off" maxlength="24" placeholder="${t('playerPlaceholder')}" aria-label="${t('playerPlaceholder')}"/><button class="secondary" type="submit">＋ ${t('addPlayer')}</button></form><div class="player-list">${state.players.map((name,i)=>`<span class="player-chip"><em>${i+1}</em>${escapeHtml(name)}<button type="button" data-remove-player="${i}" aria-label="${t('removePlayer')}: ${escapeHtml(name)}">×</button></span>`).join('')}</div></div></div><div class="setup-footer"><span>${t('adult')}</span><button class="primary" data-begin>${state.editingGame?t('continue'):t('begin')} <span aria-hidden="true">→</span></button></div></section>`,'decks')}
function renderGame(){const g=state.game;if(!g||!g.order.length)return renderDecks();const title=g.id==='favorites'?t('fav'):getCat(g.id).n[state.lang];const turn=g.mode==='turns'?g.players[g.playerIndex]:null;const turnLabel=turn?`${t('yourTurn')}: ${escapeHtml(turn)}`:t('allTurn');if(g.done)return shell(`<section class="game"><div class="game-meta"><button class="back" data-go="decks">← ${t('back')}</button><span class="deck-label">${title}</span><span></span></div><article class="question-card finish-card"><div><p>${t('finished')}</p><div class="finish-actions"><button class="primary" data-restart>${t('again')}</button><button class="secondary" data-reshuffle>${t('shuffle')}</button><button class="ghost" data-go="decks">${t('other')}</button></div></div></article></section>`,'decks');const q=questions().find(x=>x.id===g.order[g.index]);const fav=state.favorites.includes(q.id);const factor=state.cardSize/100;return shell(`<section class="game"><div class="game-meta"><button class="back" data-go="decks">← ${t('back')}</button><span class="deck-label">${title}</span><span class="game-num">${g.index+1} / ${g.order.length}</span></div><div class="progress"><i style="width:${((g.index+1)/g.order.length)*100}%"></i></div><div class="turn-banner"><span class="turn-pulse"></span><strong>${turnLabel}</strong><button data-edit-game>${t('editGame')}</button></div><article class="question-card" style="--card-factor:${factor}"><div><span class="card-kicker">${title} · ${String(g.index+1).padStart(2,'0')}</span><p>${escapeHtml(q.text)}</p></div></article><div class="game-actions"><button class="primary" data-next>${t('next')} <span aria-hidden="true">→</span></button><button class="secondary compact" data-random>${t('random')}</button><button class="round-btn heart ${fav?'on':''}" data-favorite="${q.id}" aria-label="${t('fav')}" aria-pressed="${fav}">${fav?'♥':'♡'}</button></div><div class="game-small"><button data-skip>${t('skip')}</button><span>${g.mode==='turns'?`${g.players.length} ${t('players').toLowerCase()}`:t('everyone')}</span></div></section>`,'decks')}
function renderFavorites(){const items=state.favorites.map(id=>questionMap[id]).filter(Boolean);return shell(`<section class="content-page favorites-page"><h1 class="page-title">${t('favTitle')}</h1><p class="sub">${t('favLead')}</p>${items.length?`<p><button class="primary" data-play-fav>${t('playFav')} →</button></p><div class="fav-list">${items.map(q=>`<article class="fav-item"><div><p class="fav-meta">${getCat(q.category).n[state.lang]}</p><p>${escapeHtml((state.lang==='uk'?allQuestionsUk:allQuestions).find(x=>x.id===q.id).text)}</p></div><button class="remove" aria-label="${t('removed')}" data-remove-fav="${q.id}">×</button></article>`).join('')}</div>`:`<div class="empty">${t('emptyFav')}</div>`}</section>`,'')}
function renderAnon(){const prompts=makeQuestions('confession',state.lang);return shell(`<section class="content-page anon-page"><h1 class="page-title">${t('anonymous')}</h1><p class="sub">${t('anonLead')}</p><div class="anon-layout"><form class="conf-form" id="conf-form"><label class="field-label" for="conf-q">${t('chooseQ')}</label><select class="select" id="conf-q">${prompts.map(q=>`<option value="${escapeHtml(q.text)}">${escapeHtml(q.text)}</option>`).join('')}<option value="custom">— ${t('ownQ')} —</option></select><input id="custom-q" class="hidden" maxlength="180" placeholder="${t('ownQ')}" aria-label="${t('ownQ')}"/><label class="field-label" for="conf-text">${t('answer')}</label><textarea id="conf-text" maxlength="600" required placeholder="…"></textarea><p class="counter"><span id="char-count">0</span> / 600 ${t('count')}</p><button class="primary" type="submit">${t('add')}</button></form><div><div class="list-actions"><span>${state.confessions.length} ${state.lang==='ru'?'признаний':'зізнань'}</span><button class="secondary compact" data-mix>${t('mix')}</button>${state.confessions.length?`<button class="ghost compact" data-clear>${t('clear')}</button>`:''}</div>${state.confessions.length?`<div class="conf-list">${state.confessions.map((x,i)=>`<article class="conf-card"><div class="conf-head"><p class="conf-q">#${i+1} · ${escapeHtml(x.question)}</p><button class="remove" data-delete-conf="${x.id}" aria-label="${t('clear')}">×</button></div><p class="conf-text">${escapeHtml(x.text)}</p></article>`).join('')}</div>`:`<div class="empty">${t('noConf')}</div>`}</div></div></section>`,'anon')}
function renderSettings(){const ru=state.lang==='ru';return shell(`<section class="content-page settings"><p class="eyebrow">${t('settingsHint')}</p><h1 class="page-title">${t('settings')}</h1><div class="settings-panel"><div class="setting-row"><div><h3>${t('language')}</h3><p>Русский / Українська</p></div><div class="segmented"><button class="${state.lang==='ru'?'selected':''}" data-lang="ru" aria-pressed="${state.lang==='ru'}">RU</button><button class="${state.lang==='uk'?'selected':''}" data-lang="uk" aria-pressed="${state.lang==='uk'}">UK</button></div></div><div class="setting-row"><div><h3>${ru?'Тема':'Тема'}</h3><p>${ru?'Оформление приложения':'Оформлення застосунку'}</p></div><div class="segmented"><button class="${!state.dark?'selected':''}" data-set-theme="light" aria-label="${t('light')}" aria-pressed="${!state.dark}">☀</button><button class="${state.dark?'selected':''}" data-set-theme="dark" aria-label="${t('dark')}" aria-pressed="${state.dark}">☾</button></div></div><div class="setting-row slider-row"><div><h3>${t('cardSize')}</h3><p>${ru?'Меньше — больше':'Менше — більше'}</p></div><output id="card-size-value" for="card-size">${state.cardSize}%</output><input id="card-size" type="range" min="85" max="115" value="${state.cardSize}" aria-label="${t('cardSize')}" /></div><div class="setting-row"><div><h3>${t('sound')}</h3><p>${ru?'Сигнал при смене карточки':'Сигнал під час зміни картки'}</p></div><button class="secondary compact toggle" data-toggle-sound aria-pressed="${state.sound}">${state.sound?ru?'Вкл':'Увімк':ru?'Выкл':'Вимк'}</button></div></div><div class="settings-note"><h2>${t('rules')}</h2><p>${t('rulesText')}</p><h2>${t('privacy')}</h2><p>${t('privacyText')}</p></div><div class="settings-danger"><button class="ghost compact" data-clear-fav>${t('clearFav')}</button><button class="ghost compact" data-reset>${t('reset')}</button></div></section>`,'')}
function modal(){const m=state.modal;if(m==='warning')return `<div class="modal-layer"><section class="modal"><p class="eyebrow">18+</p><h2>${t('warningTitle')}</h2><p>${t('warning')}</p><div class="modal-actions"><button class="ghost" data-close-modal>${t('cancel')}</button><button class="primary" data-accept>${t('accept')}</button></div></section></div>`;return `<div class="modal-layer"><section class="modal"><h2>${t('confirmClear')}</h2><p>${t('privacyText')}</p><div class="modal-actions"><button class="ghost" data-close-modal>${t('cancel')}</button><button class="primary" data-confirm-clear>${t('confirm')}</button></div></section></div>`}
let lastRenderedView=null;
function render(){setTheme();let body=state.view==='home'?renderHome():state.view==='decks'?renderDecks():state.view==='setup'?renderSetup():state.view==='game'?renderGame():state.view==='favorites'?renderFavorites():state.view==='anonymous'?renderAnon():renderSettings();$('#app').innerHTML=body;if(state.view!==lastRenderedView){window.scrollTo(0,0);lastRenderedView=state.view;}}
function toast(msg){state.toast=msg;render();setTimeout(()=>{state.toast='';render()},1800)}
function selectDeck(id){state.selectedDeck=id;state.editingGame=false;state.view='setup';render();}
function startDeck(id){const qs=id==='favorites'?state.favorites.filter(x=>questions().some(q=>q.id===x)):questions().filter(q=>q.category===id).map(q=>q.id);if(!qs.length)return;if(state.mode==='turns'&&!state.players.length){toast(t('noPlayers'));return}if(state.editingGame&&state.game?.id===id){state.game.mode=state.mode;state.game.players=[...state.players];state.game.playerIndex=state.game.playerIndex%Math.max(1,state.players.length)}else state.game={id,mode:state.mode,players:[...state.players],playerIndex:0,order:state.mode==='turns'?shuffle(qs):[...qs],index:0,done:false};state.editingGame=false;state.view='game';render();}
function tone(){if(!state.sound)return;try{const c=new AudioContext(),o=c.createOscillator(),g=c.createGain();o.frequency.value=520;g.gain.setValueAtTime(.03,c.currentTime);o.connect(g).connect(c.destination);o.start();o.stop(c.currentTime+.055)}catch{}}
function advance(random=false){const g=state.game;if(!g||g.done)return;if(g.index>=g.order.length-1){g.done=true;render();window.scrollTo(0,0);return}if(random){const rest=g.order.slice(g.index+1),pick=Math.floor(Math.random()*rest.length);[g.order[g.index+1],g.order[g.index+1+pick]]=[g.order[g.index+1+pick],g.order[g.index+1]]}g.index++;if(g.mode==='turns'&&g.players.length)g.playerIndex=(g.playerIndex+1)%g.players.length;tone();render();window.scrollTo(0,0);}
function favorite(id){state.favorites=state.favorites.includes(id)?state.favorites.filter(x=>x!==id):[...state.favorites,id];store.set('favorites',state.favorites);toast(state.favorites.includes(id)?t('saved'):t('removed'));}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.go){state.view=b.dataset.go;state.modal=null;render();return}
 if(b.hasAttribute('data-start')){if(store.get('warned',false)){state.view='decks';render()}else{state.modal='warning';render()}return}
 if(b.hasAttribute('data-close-modal')){state.modal=null;render();return}
 if(b.hasAttribute('data-accept')){store.set('warned',true);state.modal=null;state.view='decks';render();return}
 if(b.dataset.deck){selectDeck(b.dataset.deck);return}
 if(b.hasAttribute('data-random-deck')){selectDeck(cats[Math.floor(Math.random()*cats.length)].id);return}
 if(b.hasAttribute('data-play-fav')){selectDeck('favorites');return}
 if(b.dataset.mode){state.mode=b.dataset.mode;store.set('mode',state.mode);render();return}
 if(b.dataset.removePlayer!==undefined){state.players.splice(Number(b.dataset.removePlayer),1);store.set('players',state.players);render();return}
 if(b.hasAttribute('data-begin')){startDeck(state.selectedDeck);return}
 if(b.hasAttribute('data-edit-game')){state.selectedDeck=state.game.id;state.mode=state.game.mode;state.players=[...state.game.players];state.editingGame=true;state.view='setup';render();return}
 if(b.hasAttribute('data-next')||b.hasAttribute('data-skip')){advance();return}
 if(b.hasAttribute('data-random')){advance(true);return}
 if(b.dataset.favorite){favorite(b.dataset.favorite);return}
 if(b.dataset.removeFav){state.favorites=state.favorites.filter(x=>x!==b.dataset.removeFav);store.set('favorites',state.favorites);render();return}
 if(b.hasAttribute('data-restart')||b.hasAttribute('data-reshuffle')){if(b.hasAttribute('data-reshuffle'))state.game.order=shuffle(state.game.order);state.game.index=0;state.game.playerIndex=0;state.game.done=false;render();return}
 if(b.hasAttribute('data-mix')){state.confessions=shuffle(state.confessions);store.set('confessions',state.confessions);render();return}
 if(b.hasAttribute('data-clear')){state.modal='clear';render();return}
 if(b.hasAttribute('data-confirm-clear')){state.confessions=[];store.set('confessions',[]);state.modal=null;render();return}
 if(b.dataset.deleteConf){state.confessions=state.confessions.filter(x=>x.id!==b.dataset.deleteConf);store.set('confessions',state.confessions);render();return}
 if(b.dataset.lang){state.lang=b.dataset.lang;store.set('lang',state.lang);render();return}
 if(b.dataset.setTheme){state.dark=b.dataset.setTheme==='dark';store.set('dark',state.dark);render();return}
 if(b.hasAttribute('data-toggle-sound')){state.sound=!state.sound;store.set('sound',state.sound);render();return}
 if(b.hasAttribute('data-clear-fav')){state.favorites=[];store.set('favorites',[]);render();return}
 if(b.hasAttribute('data-reset')){state.favorites=[];state.confessions=[];store.set('favorites',[]);store.set('confessions',[]);render()}
});
document.addEventListener('change',e=>{if(e.target.id==='lang-select'){state.lang=e.target.value;store.set('lang',state.lang);render()}if(e.target.id==='conf-q'){$('#custom-q').classList.toggle('hidden',e.target.value!=='custom')}});
document.addEventListener('input',e=>{if(e.target.id==='conf-text')$('#char-count').textContent=e.target.value.length;if(e.target.id==='card-size'){state.cardSize=Number(e.target.value);store.set('cardSize',state.cardSize);$('#card-size-value').textContent=state.cardSize+'%'}});
document.addEventListener('submit',e=>{if(e.target.id==='player-form'){e.preventDefault();const name=$('#player-name').value.trim().replace(/\s+/g,' ');if(!name)return;if(state.players.length>=20||state.players.some(x=>x.toLocaleLowerCase()===name.toLocaleLowerCase()))return;state.players.push(name);store.set('players',state.players);render();$('#player-name')?.focus();return}if(e.target.id!=='conf-form')return;e.preventDefault();const select=$('#conf-q'),custom=$('#custom-q').value.trim(),text=$('#conf-text').value.trim(),question=select.value==='custom'?custom:select.value;if(!question||!text)return;state.confessions=[{id:crypto.randomUUID(),question,text},...state.confessions];store.set('confessions',state.confessions);toast(t('added'));render()});
document.addEventListener('keydown',e=>{if(state.view!=='game'||e.target.matches('input,textarea,select'))return;if(e.key==='ArrowRight')advance();if(e.key.toLowerCase()==='s')advance();if(e.key.toLowerCase()==='r')advance(true);if(e.key.toLowerCase()==='f'){const q=questions().find(x=>x.id===state.game.order[state.game.index]);if(q)favorite(q.id)}});
setTheme();render();if('serviceWorker' in navigator)navigator.serviceWorker.register('sw.js').catch(()=>{});
